import java.time.LocalDate;

/** Model class: represents one Chama member (one row of the members table). */
public class Member {
    private int memberId;
    private String fullName;
    private String nationalId;
    private String phone;
    private String county;
    private double monthlyContribution;
    private LocalDate joinDate;

    public Member() { }

    // Constructor used when adding a new member (id is generated by MySQL)
    public Member(String fullName, String nationalId, String phone, String county,
                  double monthlyContribution, LocalDate joinDate) {
        this.fullName = fullName;
        this.nationalId = nationalId;
        this.phone = phone;
        this.county = county;
        this.monthlyContribution = monthlyContribution;
        this.joinDate = joinDate;
    }

    // Constructor used when reading an existing member from the database
    public Member(int memberId, String fullName, String nationalId, String phone,
                  String county, double monthlyContribution, LocalDate joinDate) {
        this(fullName, nationalId, phone, county, monthlyContribution, joinDate);
        this.memberId = memberId;
    }

    public int getMemberId() { return memberId; }
    public void setMemberId(int memberId) { this.memberId = memberId; }

    public String getFullName() { return fullName; }
    public void setFullName(String fullName) { this.fullName = fullName; }

    public String getNationalId() { return nationalId; }
    public void setNationalId(String nationalId) { this.nationalId = nationalId; }

    public String getPhone() { return phone; }
    public void setPhone(String phone) { this.phone = phone; }

    public String getCounty() { return county; }
    public void setCounty(String county) { this.county = county; }

    public double getMonthlyContribution() { return monthlyContribution; }
    public void setMonthlyContribution(double monthlyContribution) { this.monthlyContribution = monthlyContribution; }

    public LocalDate getJoinDate() { return joinDate; }
    public void setJoinDate(LocalDate joinDate) { this.joinDate = joinDate; }
}
